import sqlparse
from sqlparse import sql

def test_bug():
    test_sql = "select l_discount from lineitem where l_discount between .03 and .06;"
    statement = sqlparse.parse(test_sql)[0]
    for token in statement.tokens:
        if isinstance(token, sql.Where):
            for sub_token in token.tokens:
                if sub_token.value in [' ', '\n']:
                    continue
                if sub_token.value.strip().lower() == 'between':
                    assert not isinstance(sub_token, sql.Identifier)
